// IC2: original two-way I-cache implementation, parallel tag/data lookup and per-set LRU.
// R23: ready-qualified speculative I payload reads; accepted handshakes/state unchanged.
// R16: cache response data is an unqualified proposal; valid/errors and accepted-cycle payloads are unchanged.
// FPGA RAM port adaptation of the original RV32 cache.
// Generated by lower_cache_ports.py; original source SHA-256: 275eceb22039d4f0b742c922b29d101c2d13b89cf312311fb21e818901523666
// Original RV32 memory system. Designed from the neutral bus contract.
// No reference RTL, generated code, or third-party CPU implementation used.
// All cache-array reads are clocked. Instruction banks are 32 bits; data
// segments are 64 bits. Cache data/tag arrays are not reset;
// deterministic valid/dirty bits prevent uninitialized contents being observed.
// 中文架构说明  与上次130MHz实板源保持同一逻辑版本
// 两路 I-cache 与两路 D-cache，以及非缓存 MMIO 与外部行事务控制。
// I-cache 只保存指令；D-cache 使用写回与写分配，标签、valid、dirty
// 和每组替换位独立维护。
// 一行 64 字节，外部数据宽度 64 位，因此一条完整回填或写回包含 8 个数据拍。
// 指令行按奇偶 32 位字分银行，两路 way 与奇偶 bank 是两种不同的划分。
// 所有数据 RAM 读均经过时钟边界；未复位的 RAM 内容由 valid/dirty 所有权屏蔽。
// 本板 I 路选择把标签逐位相等结果寄存在已有 RAM 读边界，未增加取指事务周期。
// D 路选择在请求边界保存命中与 way；数据返回仍必须由对应 valid/error 许可。
// Cache miss 先处理脏牺牲行写回，再回填目标行；
// 写响应未到达前不能提前认为写回完成。
// MMIO 不进入 Cache，通过外围请求/应答通道返回错误与数据。
// fence_i 与 fence_d 触发维护，数据清扫需访问所有 set/way，并等待脏行写回确认。
// 跨行双指令取指、回填中错误和响应背压都保留独立状态，
// 不以原始数据变化代表接收。
// 本模块导出的 refill 事件只计行请求，未导出每次 Cache 查询总数，
// 故不能单独推算命中率。
// 接口契约与阅读示例
// I侧命中  接受地址后，在同步RAM读边界取得指令字与对应标签判等信息。
// 后续有效响应必须对应这个已接受地址，预备读产生的其他数值只能视作提案。
// I侧缺失  保存牺牲way，发出行读请求，逐个接受8个64位回填拍。
// 第二字跨64B行边界时，需要独立核对下一行标签及可执行地址。
// I-cache中的even/odd只是字银行，second后缀才代表第二相联way。
// D侧读命中  根据捕获的way选择64位段，再从段中选择CPU需要的字。
// D侧写命中  按字节掩码合并数据并标记dirty，外部SRAM此时可以仍是旧值。
// D侧读写缺失  如果牺牲行dirty，先送完整旧行，再等待写响应成功。
// 目标行回填完成后才能对已接受的Store应用写掩码，不能丢失原Store身份。
// 写回地址来自牺牲tag和set，不应与目标请求地址混用。
// 一笔外部写事务包括数据拍和确认两个阶段，最后数据拍本身不解除错误处理责任。
// 外围区访问走MMIO，不以Cache命中数据替代外设响应。
// 维护扫描覆盖每一set及每一way；脏行需先写回，随后才可失效。
// 数据RAM可以保留复位前比特，valid/dirty清除保证旧内容不可成为新命中。
// 回填中任意拍发生错误，会影响该请求的有效/错误返回，而不能仅看最后一拍。
// 复位、缺失及背压下，raw data允许变化；只有被接受的有效响应才进入CPU完成通路。
// 统计event_icache_refill只说明发起一条行读，不代表这一行服务了多少次命中。
// 因此报告保留回填计数，但没有用它伪造Cache命中率。
module rv32_memory_system #(
    // 参数 I_INDEX_BITS：I-cache组索引位宽；本板7位即128组，
    // 容量还需乘路数与64B行长。
    parameter I_INDEX_BITS = 7,
    // 参数 I_WAYS：I-cache组相联路数；本板2路，奇偶字银行并非路数。
    parameter I_WAYS = 2,
    // 参数 D_INDEX_BITS：D-cache组索引位宽；本板6位即64组。
    parameter D_INDEX_BITS = 6,
    // 参数 D_WAYS：D-cache组相联路数；本板2路，每路拥有独立tag/valid/dirty。
    parameter D_WAYS = 2,
    // Opt-in parallel next-line tag lookup. Data-bank ports remain synchronous.
    // 参数 ENABLE_FAST_ICROSS：双指令取指跨行且两行命中时使用并行下一行标签信息
    // ；错误/缺失保持原状态流程。
    parameter ENABLE_FAST_ICROSS = 0,
    // Optional board-map knowledge, disabled for reusable/DDR systems. Bounds
    // are inclusive and line aligned. No address addition can wrap at 4 GiB.
    // 参数 ENABLE_DATA_RAM_GUARD：启用板级RAM边界知识，防止越界行访问；
    // 不是MMU或页级权限机制。
    parameter ENABLE_DATA_RAM_GUARD = 0,
    // 参数 DATA_RAM_BASE：本板可访问RAM的包含式低边界，0x10000000。
    parameter [31:0] DATA_RAM_BASE = 32'h00000000,
    // 参数 DATA_RAM_LIMIT：本板可访问RAM的包含式高边界，0x1000ffff。
    parameter [31:0] DATA_RAM_LIMIT = 32'hffffffff
)(
    // 接口字段：input clk, reset。
    // 时钟/复位/取消控制。同步状态在指定边界更新；
    // cancel清除所有权而非创造成功响应。
    input clk, reset,
    // 接口字段：input imem_request_valid, output imem_request_ready。
    // 事务握手。valid与对应ready同边界才接收；背压期间有主状态的载荷必须保持。
    input imem_request_valid, output imem_request_ready,
    // 接口字段：input [31:0] imem_request_address。
    // 访存载荷或字节控制。地址、大小与字节掩码必须属于同一笔已接受事务。
    input [31:0] imem_request_address,
    // 接口字段：output reg imem_response_valid, input imem_response_ready。
    // 事务握手。valid与对应ready同边界才接收；背压期间有主状态的载荷必须保持。
    output reg imem_response_valid, input imem_response_ready,
    // 接口字段：output reg [63:0] imem_response_data。
    // 两路 I-cache 与两路 D-cache，以及非缓存 MMIO 与外部行事务控制。
    output reg [63:0] imem_response_data,
    // 接口字段：output reg [1:0] imem_response_error。
    // 错误或非法资格。需随相应有效指令/事务传播，最终在精确提交边界处理。
    output reg [1:0] imem_response_error,
    // 接口字段：input dmem_request_valid, output dmem_request_ready。
    // 事务握手。valid与对应ready同边界才接收；背压期间有主状态的载荷必须保持。
    input dmem_request_valid, output dmem_request_ready,
    // 接口字段：input [31:0] dmem_request_address。
    // 访存载荷或字节控制。地址、大小与字节掩码必须属于同一笔已接受事务。
    input [31:0] dmem_request_address,
    // 接口字段：input dmem_request_write。
    // 访存载荷或字节控制。地址、大小与字节掩码必须属于同一笔已接受事务。
    input dmem_request_write,
    // 接口字段：input [31:0] dmem_request_wdata。
    // 访存载荷或字节控制。地址、大小与字节掩码必须属于同一笔已接受事务。
    input [31:0] dmem_request_wdata,
    // 接口字段：input [3:0] dmem_request_wstrb。
    // 访存载荷或字节控制。地址、大小与字节掩码必须属于同一笔已接受事务。
    input [3:0] dmem_request_wstrb,
    // 接口字段：input [1:0] dmem_request_size。
    // 访存载荷或字节控制。地址、大小与字节掩码必须属于同一笔已接受事务。
    input [1:0] dmem_request_size,
    // 接口字段：output reg dmem_response_valid, input dmem_response_ready。
    // 事务握手。valid与对应ready同边界才接收；背压期间有主状态的载荷必须保持。
    output reg dmem_response_valid, input dmem_response_ready,
    // 接口字段：output reg [31:0] dmem_response_rdata。
    // 访存载荷或字节控制。地址、大小与字节掩码必须属于同一笔已接受事务。
    output reg [31:0] dmem_response_rdata,
    // 接口字段：output reg dmem_response_error。
    // 错误或非法资格。需随相应有效指令/事务传播，最终在精确提交边界处理。
    output reg dmem_response_error,
    // 接口字段：input fence_i, fence_d。
    // Cache维护请求或忙状态。脏行写回及外部确认完成前不能提前结束维护。
    input fence_i, fence_d,
    // 接口字段：output maintenance_busy。
    // Cache维护请求或忙状态。脏行写回及外部确认完成前不能提前结束维护。
    output maintenance_busy,
    // 接口字段：output event_icache_refill, event_dcache_refill,
    // event_dcache_writeback。
    // 访存载荷或字节控制。地址、大小与字节掩码必须属于同一笔已接受事务。
    output event_icache_refill, event_dcache_refill, event_dcache_writeback,
    // 接口字段：output instr_req_o, input instr_gnt_i。
    // 外部事务通道。req/gnt许可请求，rvalid/rready或写响应确认返回；
    // 数据变化不等于完成。
    output instr_req_o, input instr_gnt_i,
    // 接口字段：output [31:0] instr_addr_o, output instr_io_o。
    // 访存载荷或字节控制。地址、大小与字节掩码必须属于同一笔已接受事务。
    output [31:0] instr_addr_o, output instr_io_o,
    // 接口字段：input instr_rvalid_i, output instr_rready_o。
    // 外部事务通道。req/gnt许可请求，rvalid/rready或写响应确认返回；
    // 数据变化不等于完成。
    input instr_rvalid_i, output instr_rready_o,
    // 接口字段：input [63:0] instr_rdata_i, input instr_err_i。
    // 错误或非法资格。需随相应有效指令/事务传播，最终在精确提交边界处理。
    input [63:0] instr_rdata_i, input instr_err_i,
    // 接口字段：output data_rd_req_o, input data_rd_gnt_i。
    // 外部事务通道。req/gnt许可请求，rvalid/rready或写响应确认返回；
    // 数据变化不等于完成。
    output data_rd_req_o, input data_rd_gnt_i,
    // 接口字段：output data_rd_id_o, output [31:0] data_rd_addr_o。
    // 访存载荷或字节控制。地址、大小与字节掩码必须属于同一笔已接受事务。
    output data_rd_id_o, output [31:0] data_rd_addr_o,
    // 接口字段：input data_rd_rvalid_i, output data_rd_rready_o。
    // 外部事务通道。req/gnt许可请求，rvalid/rready或写响应确认返回；
    // 数据变化不等于完成。
    input data_rd_rvalid_i, output data_rd_rready_o,
    // 接口字段：input data_rd_rid_i, input [63:0] data_rd_rdata_i。
    // 访存载荷或字节控制。地址、大小与字节掩码必须属于同一笔已接受事务。
    input data_rd_rid_i, input [63:0] data_rd_rdata_i,
    // 接口字段：input data_rd_err_i。
    // 错误或非法资格。需随相应有效指令/事务传播，最终在精确提交边界处理。
    input data_rd_err_i,
    // 接口字段：output data_wr_req_o, input data_wr_gnt_i。
    // 外部事务通道。req/gnt许可请求，rvalid/rready或写响应确认返回；
    // 数据变化不等于完成。
    output data_wr_req_o, input data_wr_gnt_i,
    // 接口字段：output data_wr_last_o, output [31:0] data_wr_addr_o。
    // 访存载荷或字节控制。地址、大小与字节掩码必须属于同一笔已接受事务。
    output data_wr_last_o, output [31:0] data_wr_addr_o,
    // 接口字段：output [63:0] data_wr_data_o, output data_wr_id_o。
    // 两路 I-cache 与两路 D-cache，以及非缓存 MMIO 与外部行事务控制。
    output [63:0] data_wr_data_o, output data_wr_id_o,
    // 接口字段：input data_wr_bvalid_i, input data_wr_berr_i, input
    // data_wr_bid_i。
    // 外部事务通道。req/gnt许可请求，rvalid/rready或写响应确认返回；
    // 数据变化不等于完成。
    input data_wr_bvalid_i, input data_wr_berr_i, input data_wr_bid_i,
    // 接口字段：output periph_req_o, input periph_gnt_i。
    // 外部事务通道。req/gnt许可请求，rvalid/rready或写响应确认返回；
    // 数据变化不等于完成。
    output periph_req_o, input periph_gnt_i,
    // 接口字段：output periph_we_o, output [31:0] periph_addr_o。
    // 访存载荷或字节控制。地址、大小与字节掩码必须属于同一笔已接受事务。
    output periph_we_o, output [31:0] periph_addr_o,
    // 接口字段：output [31:0] periph_wdata_o, output [3:0] periph_be_o。
    // 访存载荷或字节控制。地址、大小与字节掩码必须属于同一笔已接受事务。
    output [31:0] periph_wdata_o, output [3:0] periph_be_o,
    // 接口字段：output [1:0] periph_size_o。
    // 访存载荷或字节控制。地址、大小与字节掩码必须属于同一笔已接受事务。
    output [1:0] periph_size_o,
    // 接口字段：input periph_rvalid_i, input periph_err_i。
    // 外部事务通道。req/gnt许可请求，rvalid/rready或写响应确认返回；
    // 数据变化不等于完成。
    input periph_rvalid_i, input periph_err_i,
    // 接口字段：input [31:0] periph_rdata_i。
    // 访存载荷或字节控制。地址、大小与字节掩码必须属于同一笔已接受事务。
    input [31:0] periph_rdata_i
);
    // Cache容量按组数乘路数乘64字节计算，不能把偶/奇银行数量再当路数相乘。
    // 本板I=16KiB、D=8KiB，外部每行8个64位数据拍。
    localparam I_LINES = (1 << I_INDEX_BITS);
    localparam D_LINES = (1 << D_INDEX_BITS);
    localparam I_TAG_BITS = 26-I_INDEX_BITS;
    localparam D_TAG_BITS = 26-D_INDEX_BITS;
    localparam [2:0] I_IDLE=0, I_LOOKUP=1, I_COMMAND=2,
                     I_FILL=3, I_ERROR=4;
    localparam [3:0] D_IDLE=0, D_LOOKUP=1, D_READ_COMMAND=2,
                     D_FILL=3, D_WRITE_BEATS=4, D_WRITE_ACK=5,
                     D_IO_COMMAND=6, D_IO_WAIT=7, D_RESPONSE=8,
                     D_SWEEP_READ=9, D_SWEEP_CHECK=10, D_WRITE_READ=11;

    (* syn_ramstyle="block_ram" *)reg [31:0] instruction_even [0:I_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [31:0] instruction_odd [0:I_LINES*8-1];
    (* syn_ramstyle="lut_ram" *) reg [I_TAG_BITS-1:0] instruction_tags [0:I_LINES-1];
    reg instruction_valid [0:I_LINES-1];
    // Each set has two independent tags and two 64-byte lines. Even/odd
    // banks are word banks within a way; both ways are read in parallel.
    (* syn_ramstyle="block_ram" *)reg [31:0] instruction_even_second [0:I_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [31:0] instruction_odd_second [0:I_LINES*8-1];
    (* syn_ramstyle="lut_ram" *) reg [I_TAG_BITS-1:0] instruction_tags_second [0:I_LINES-1];
    reg instruction_valid_second [0:I_LINES-1];
    reg instruction_lru [0:I_LINES-1];
    (* syn_ramstyle="block_ram" *)reg [7:0] data_segments_byte0 [0:D_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [7:0] data_segments_byte1 [0:D_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [7:0] data_segments_byte2 [0:D_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [7:0] data_segments_byte3 [0:D_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [7:0] data_segments_byte4 [0:D_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [7:0] data_segments_byte5 [0:D_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [7:0] data_segments_byte6 [0:D_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [7:0] data_segments_byte7 [0:D_LINES*8-1];
    reg [D_TAG_BITS-1:0] data_tags [0:D_LINES-1];
    reg data_valid [0:D_LINES-1];
    reg data_dirty [0:D_LINES-1];
    (* syn_ramstyle="block_ram" *)reg [7:0] data_segments_second_byte0 [0:D_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [7:0] data_segments_second_byte1 [0:D_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [7:0] data_segments_second_byte2 [0:D_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [7:0] data_segments_second_byte3 [0:D_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [7:0] data_segments_second_byte4 [0:D_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [7:0] data_segments_second_byte5 [0:D_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [7:0] data_segments_second_byte6 [0:D_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [7:0] data_segments_second_byte7 [0:D_LINES*8-1];
    reg [D_TAG_BITS-1:0] data_tags_second [0:D_LINES-1];
    reg data_valid_second [0:D_LINES-1];
    reg data_dirty_second [0:D_LINES-1];
    reg data_lru [0:D_LINES-1];

    // I侧状态拥有一笔取指响应及跨行首字信息；原始RAM输出会随提案地址变化。
    // 只有imem_response_valid与error位才能赋予返回字实际指令意义。
    reg [2:0] i_state;
    reg [31:0] i_address;
    wire [31:0] i_even_word, i_odd_word;
    wire [31:0] i_word0=i_address[2] ? i_odd_word : i_even_word;
    wire [31:0] i_word1=i_address[2] ? i_even_word : i_odd_word;
    reg [I_TAG_BITS-1:0] i_tag;
    reg i_valid;
    reg [I_TAG_BITS-1:0] i_next_tag;
    reg i_next_valid;
    reg [I_TAG_BITS-1:0] i_second_tag, i_next_second_tag;
    reg i_second_valid, i_next_second_valid, i_lru, i_refill_way;
    reg i_crossing;
    reg [31:0] i_first_word;
    reg i_first_error;
    reg [2:0] i_beat;
    reg i_fill_error;
    // R48: all original error payload upper words are zero. Only validity
    // receives late ownership/error decisions. Raw lower-word proposals use
    // registered cache state/address and are private outside I_ERROR.
    reg [63:0] i_error_data_snapshot;
    reg [31:0] i_error_word;
    reg i_error_word_valid;
    wire [63:0] i_error_data={32'b0,i_error_word_valid?i_error_word:32'b0};
`ifdef VERILATOR
    always @(posedge clk)if(!reset&&i_state==I_ERROR&&i_error_data!=i_error_data_snapshot)
        $fatal(1,"R48 owned error payload differs from original cache register");
`endif
    reg [1:0] i_error_bits;
    wire [I_INDEX_BITS-1:0] i_index = i_address[6+I_INDEX_BITS-1:6];
    wire i_match_first = i_valid && i_tag == i_address[31:6+I_INDEX_BITS];
    wire i_match_second = I_WAYS>1 && i_second_valid && i_second_tag == i_address[31:6+I_INDEX_BITS];
    wire i_hit = i_match_first || i_match_second;
    wire i_hit_way = i_match_second;
    wire i_victim_way = I_WAYS>1 && (i_valid && (!i_second_valid || i_lru));
    wire [31:0] i_next_address = i_address + 32'd4;
    wire [I_INDEX_BITS-1:0] i_next_index = i_next_address[6+I_INDEX_BITS-1:6];
    // The normal even-bank request read already addresses word1 across a line.
    // Its separate, clocked tag/valid snapshot grants that payload ownership
    // only when both lines hit and the second word remains executable. Nothing
    // changes on a miss or fault; those retain the original precise sequence.
    wire i_next_match_first = i_next_valid && i_next_tag==i_next_address[31:6+I_INDEX_BITS];
    wire i_next_match_second = I_WAYS>1 && i_next_second_valid && i_next_second_tag==i_next_address[31:6+I_INDEX_BITS];
    wire i_next_hit_way = i_next_match_second;
    wire i_fast_cross_hit = ENABLE_FAST_ICROSS && !i_crossing &&
        i_address[5:2]==4'd15 && executable(i_next_address) &&
        (i_next_match_first || i_next_match_second);
    wire [31:0] new_i_next_address = imem_request_address + 32'd4;
    wire [I_INDEX_BITS-1:0] new_i_next_index = new_i_next_address[6+I_INDEX_BITS-1:6];

    // D侧独立保存访存大小、写掩码、命中路和回填/牺牲行身份。
    // writeback_way与request_way属于不同事务，写回不能覆盖目标回填元数据。
    reg [3:0] d_state;
    reg [31:0] d_address;
    reg d_write;
    reg [31:0] d_wdata;
    reg [3:0] d_wstrb;
    reg [1:0] d_size;
    wire [63:0] d_segment, d_second_segment;
    reg [D_TAG_BITS-1:0] d_tag;
    reg d_valid, d_dirty;
    reg [D_TAG_BITS-1:0] d_second_tag;
    reg d_second_valid, d_second_dirty, d_lru;
    reg request_way, writeback_way, sweep_way;
    reg [2:0] d_beat;
    reg d_fill_error;
    reg [31:0] d_result;
    reg d_result_error;
    reg [31:0] writeback_address;
    reg [D_INDEX_BITS-1:0] writeback_index;
    reg writeback_is_sweep;
    reg [D_INDEX_BITS-1:0] sweep_index;
    reg fence_pending, invalidate_data;
    wire [D_INDEX_BITS-1:0] d_index = d_address[6+D_INDEX_BITS-1:6];
    // Soc03: snapshot hit and way at the existing request/tag-read edge.
    // This removes post-register tag equality from response/wakeup/redirect.
    reg d_match_first,d_match_second,selected_way;
    wire d_hit = d_match_first || d_match_second;
    wire selected_valid=selected_way ? d_second_valid : d_valid;
    wire selected_dirty=selected_way ? d_second_dirty : d_dirty;
    wire [D_TAG_BITS-1:0] selected_tag=selected_way ? d_second_tag : d_tag;
    wire [63:0] selected_segment=selected_way ? d_second_segment : d_segment;
    wire sweep_is_last=(sweep_index==D_LINES-1) && (D_WAYS==1 || sweep_way);
    // 响应消费仅在valid和ready同时满足时发生，数据变化不代表消费。
    // 新请求的接受可能与旧响应消费同边沿发生，状态更新须保留旧所有者语义。
    wire i_complete = imem_response_valid && imem_response_ready;
    wire d_complete = dmem_response_valid && dmem_response_ready;
    wire new_i = imem_request_valid && imem_request_ready;
    // A speculative RAM/tag payload read grants no request/state ownership.
    // Ready is true only at idle or an actual response transfer, so a held
    // valid response cannot be overwritten. Remove frontend late correction
    // /request_valid from the synchronous RAM read-address selection.
    // Payload reads are safe at every idle/response-transfer edge, including
    // non-executable or unaligned private addresses. Actual new_i ownership
    // still validates the full address and returns the original precise error.
    // Never overwrite a held response: ready remains false under backpressure.
    // Maintenance still blocks actual request readiness/ownership. Reading
    // private payload while idle (or consuming a real held response) cannot
    // acquire state, and avoids a late fence/recovery cone on RAM addresses.
    wire i_speculative_read=!reset&&(i_state==I_IDLE||i_complete);
    wire new_d = dmem_request_valid && dmem_request_ready;
    wire maintenance_request = fence_pending || fence_i || fence_d;
    // Free payload capture does not acquire a request, change state, or
    // start an IO transaction. Maintenance and held responses retain fields.
    wire d_payload_free=dmem_request_ready;
    wire d_speculative_read=!reset&&(d_state==D_IDLE||d_complete);

`ifdef VERILATOR
    reg prior_d_owned;
    reg [70:0] prior_d_payload;
    always @(posedge clk)begin
        if(reset)begin prior_d_owned<=0;prior_d_payload<=0;end
        else begin
            if(new_d&&!d_payload_free)$fatal(1,"R42 accepted data request without free private payload slot");
            if(prior_d_owned&&{d_address,d_write,d_wdata,d_wstrb,d_size}!=prior_d_payload)
                $fatal(1,"R42 owned cache request payload differs from original accepted request");
            if(new_d)begin prior_d_owned<=1;prior_d_payload<=
                {dmem_request_address,dmem_request_write,dmem_request_wdata,dmem_request_wstrb,dmem_request_size};end
            else if(d_complete)prior_d_owned<=0;
        end
    end
`endif
    wire [D_INDEX_BITS-1:0] next_d_index = dmem_request_address[6+D_INDEX_BITS-1:6];
    wire incoming_d_match_first=data_valid[next_d_index]&&
        data_tags[next_d_index]==dmem_request_address[31:6+D_INDEX_BITS];
    wire incoming_d_match_second=D_WAYS>1&&data_valid_second[next_d_index]&&
        data_tags_second[next_d_index]==dmem_request_address[31:6+D_INDEX_BITS];
    // A completed store/load updates LRU on the same edge as a new read.
    // Apply the existing LRU bypass before selecting a new miss victim.
    wire incoming_d_lru=(d_complete&&d_state==D_LOOKUP&&next_d_index==d_index)?
        !selected_way:data_lru[next_d_index];
    wire incoming_d_way=incoming_d_match_first?1'b0:incoming_d_match_second?1'b1:
        !data_valid[next_d_index]?1'b0:(D_WAYS>1&&!data_valid_second[next_d_index])?1'b1:
        (D_WAYS>1&&incoming_d_lru);
    always @(posedge clk)begin
        if(reset)begin d_match_first<=0;d_match_second<=0;selected_way<=0;end
        else begin
            // A successful fill changes one captured tag to this request.
            // The other captured way and address are stable throughout fill.
            if(d_state==D_FILL&&data_rd_rvalid_i&&d_beat==3'd7&&
               !d_fill_error&&!data_rd_err_i&&data_rd_rid_i==1'b0)begin
                if(request_way)d_match_second<=1;else d_match_first<=1;
                selected_way<=request_way;
            end
            if(d_speculative_read)begin
                d_match_first<=incoming_d_match_first;
                d_match_second<=incoming_d_match_second;
                selected_way<=incoming_d_way;
            end
        end
    end
`ifdef VERILATOR
    wire reference_d_match0=d_valid&&d_tag==d_address[31:6+D_INDEX_BITS];
    wire reference_d_match1=D_WAYS>1&&d_second_valid&&d_second_tag==d_address[31:6+D_INDEX_BITS];
    wire reference_d_way=reference_d_match0?1'b0:reference_d_match1?1'b1:
        !d_valid?1'b0:(D_WAYS>1&&!d_second_valid)?1'b1:(D_WAYS>1&&d_lru);
    always @(posedge clk)if(!reset&&d_state==D_LOOKUP)begin
        if(d_match_first!=reference_d_match0||d_match_second!=reference_d_match1||selected_way!=reference_d_way)
            $fatal(1,"Soc03 D-cache registered lookup differs from captured tags/LRU");
    end
`endif
    wire [D_INDEX_BITS+2:0] d_segment_index=d_address[6+D_INDEX_BITS-1:3];
    wire [D_INDEX_BITS+2:0] next_d_segment=dmem_request_address[6+D_INDEX_BITS-1:3];
    wire [I_INDEX_BITS+2:0] new_i_pair=imem_request_address[6+I_INDEX_BITS-1:3];
    wire [I_INDEX_BITS+2:0] new_i_even_pair=new_i_pair+{{(I_INDEX_BITS+2){1'b0}},imem_request_address[2]};
    wire [I_INDEX_BITS+2:0] cross_i_pair=i_next_address[6+I_INDEX_BITS-1:3];
    wire [2:0] next_write_beat=d_beat+3'd1;
    wire [7:0] store_byte_enable=d_address[2] ? {d_wstrb,4'b0} : {4'b0,d_wstrb};
    wire [63:0] store_replicated={d_wdata,d_wdata};
    integer n;

    // 函数 executable：检查取指地址是否位于本实现可执行区域，
    // 跨行第二字也必须独立满足许可。
    // 调用字段：input [31:0] address。
    // 返回值是局部组合计算；调用者继续负责有效性、标签或表项命中条件。
    function executable;
        input [31:0] address;
        begin executable = (address[31:28]==4'h1 || address[31:28]==4'h8); end
    endfunction
    // 函数 peripheral：判断外设区间；处于该范围的访问必须保留外设副作用语义，
    // 不能按普通 Cache 行拆分。
    // 调用字段：input [31:0] address。
    // 返回值是局部组合计算；调用者继续负责有效性、标签或表项命中条件。
    function peripheral;
        input [31:0] address;
        begin
            peripheral = ((address >= 32'h30000000 && address < 32'h80000000) ||
                          (address >= 32'h80000000 && address < 32'h84000000));
        end
    endfunction
    // 函数 data_ram_mapped：判断完整数据访问是否位于板级声明的RAM范围，
    // 开启guard时阻止行请求越过存储边界。
    // 调用字段：input [31:0] address。
    // 返回值是局部组合计算；调用者继续负责有效性、标签或表项命中条件。
    function data_ram_mapped;
        input [31:0] address;
        begin
            data_ram_mapped = !ENABLE_DATA_RAM_GUARD ||
                (address >= DATA_RAM_BASE && address <= DATA_RAM_LIMIT);
        end
    endfunction
`ifdef VERILATOR
    initial if (ENABLE_DATA_RAM_GUARD &&
        (DATA_RAM_BASE > DATA_RAM_LIMIT || DATA_RAM_BASE[5:0] != 0 ||
         DATA_RAM_LIMIT[5:0] != 6'h3f))
        $fatal(1,"Data RAM guard requires a nonwrapping, whole-cache-line range");
`endif
    // CPU侧32位字节掩码对应64位段中的某半字，合并只更新被选字节。
    // 未命中的Store先分配并回填目标行，再按同样的字节语义更新。
    // 函数 merge_store：将CPU的32位写数据和字节选通合并到64位Cache段，
    // 仅改变被选中的字节。
    // 调用字段：input [63:0] segment；input [63:0] value；input [7:0] enables。
    // 返回值是局部组合计算；调用者继续负责有效性、标签或表项命中条件。
    function [63:0] merge_store;
        input [63:0] segment;
        input [63:0] value;
        input [7:0] enables;
        integer lane;
        begin
            merge_store=segment;
            for(lane=0;lane<8;lane=lane+1)
                if(enables[lane])merge_store[lane*8 +: 8]=value[lane*8 +: 8];
        end
    endfunction
    wire [63:0] updated_data_segment=merge_store(selected_segment,store_replicated,store_byte_enable);

    assign maintenance_busy=maintenance_request;
    assign event_icache_refill=!reset && i_state==I_FILL && i_beat==3'd7 &&
        instr_rvalid_i && !i_fill_error && !instr_err_i;
    assign event_dcache_refill=!reset && d_state==D_FILL && d_beat==3'd7 &&
        data_rd_rvalid_i && !d_fill_error && !data_rd_err_i && data_rd_rid_i==1'b0;
    assign event_dcache_writeback=!reset && data_wr_bvalid_i && !data_wr_berr_i &&
        data_wr_bid_i==1'b0 && (d_state==D_WRITE_ACK ||
        (d_state==D_WRITE_BEATS && d_beat==3'd7 && data_wr_gnt_i));
    assign imem_request_ready=!reset && !maintenance_request &&
                             (i_state==I_IDLE || i_complete);
    assign dmem_request_ready=!reset && !maintenance_request &&
                             (d_state==D_IDLE || d_complete);
    assign instr_req_o=!reset && i_state==I_COMMAND;
    assign instr_addr_o={i_address[31:6],6'b0};
    assign instr_io_o=peripheral(i_address);
    assign instr_rready_o=!reset && (i_state==I_FILL || i_state==I_COMMAND);
    assign data_rd_req_o=!reset && d_state==D_READ_COMMAND;
    assign data_rd_id_o=1'b0;
    assign data_rd_addr_o={d_address[31:6],6'b0};
    assign data_rd_rready_o=!reset && (d_state==D_FILL || d_state==D_READ_COMMAND);
    assign data_wr_req_o=!reset && d_state==D_WRITE_BEATS;
    assign data_wr_last_o=d_beat==3'd7;
    assign data_wr_addr_o=writeback_address;
    assign data_wr_data_o=writeback_way ? d_second_segment : d_segment;
    assign data_wr_id_o=1'b0;
    assign periph_req_o=!reset && d_state==D_IO_COMMAND;
    assign periph_we_o=d_write;
    assign periph_addr_o=d_address;
    assign periph_wdata_o=d_wdata;
    assign periph_be_o=d_write ? d_wstrb :
                       (d_size==0 ? (4'b0001 << d_address[1:0]) :
                        d_size==1 ? (4'b0011 << d_address[1:0]) : 4'b1111);
    assign periph_size_o=d_size;

    always @* begin
        imem_response_valid=1'b0;
        // Data proposals are available in parallel with tag comparison.
        // Only response_valid grants a transaction; invalid-cycle data is
        // deliberately unspecified, avoiding hit -> data -> predict feedback.
        imem_response_data=i_crossing?{i_word0,i_first_word}:{i_word1,i_word0};
        imem_response_error=2'b0;
        if (!reset && i_state==I_LOOKUP && i_hit &&
            (i_crossing || i_address[5:2]!=4'd15 || i_fast_cross_hit)) begin
            imem_response_valid=1'b1;
            if(i_crossing)imem_response_error={1'b0,i_first_error};
        end
        if (!reset && i_state==I_ERROR) begin
            imem_response_valid=1'b1;
            imem_response_data=i_error_data;
            imem_response_error=i_error_bits;
        end
        dmem_response_valid=1'b0;
        dmem_response_rdata=(d_address[2]?selected_segment[63:32]:selected_segment[31:0]);
        dmem_response_error=1'b0;
        if (!reset && d_state==D_LOOKUP && d_hit) begin
            dmem_response_valid=1'b1;
        end
        if (!reset && d_state==D_RESPONSE) begin
            dmem_response_valid=1'b1;
            dmem_response_rdata=d_result;
            dmem_response_error=d_result_error;
        end
    end


    reg [31:0] i_even_ram_q, i_even_bypass;
    reg i_even_ram_select;
    reg [31:0] i_even_second_ram_q, i_odd_second_ram_q;
    // Select each bank's way at the payload-read edge, before the response
    // cycle. Independent registered tag checks still own response validity.
    // A miss uses the existing refill bypass, including cross-line requests.
    // Retiming within the existing read/response boundary: capture per-bit
    // equality, then reduce in the response cycle. No request latency added.
    reg [I_TAG_BITS-1:0] i_even_way_equal, i_odd_way_equal;
    // I路选择对已有边界寄存的逐位标签相等结果做归约。
    // 这是130MHz已上板改动，不能替换成后来150MHz候选的不同标签组织。
    wire i_even_read_way=I_WAYS>1 && (&i_even_way_equal);
    wire i_odd_read_way=I_WAYS>1 && (&i_odd_way_equal);
    assign i_even_word=i_even_ram_select ? (i_even_read_way ? i_even_second_ram_q : i_even_ram_q) : i_even_bypass;
    reg [31:0] i_odd_ram_q, i_odd_bypass;
    reg i_odd_ram_select;
    assign i_odd_word=i_odd_ram_select ? (i_odd_read_way ? i_odd_second_ram_q : i_odd_ram_q) : i_odd_bypass;
    reg [63:0] d_first_ram_q, d_first_bypass;
    reg d_first_ram_select;
    assign d_segment=d_first_ram_select ? d_first_ram_q : d_first_bypass;
    reg [63:0] d_second_ram_q, d_second_bypass;
    reg d_second_ram_select;
    assign d_second_segment=d_second_ram_select ? d_second_ram_q : d_second_bypass;

    wire i_ram_cross_lookup=(i_state==I_LOOKUP && i_hit && !i_crossing && !i_fast_cross_hit &&
        i_address[5:2]==4'd15 && executable(i_next_address));
    wire i_ram_cross_error=(i_state==I_FILL && instr_rvalid_i && i_beat==3'd7 &&
        (i_fill_error || instr_err_i) && !i_crossing && i_address[5:2]==4'd15 && executable(i_next_address));
    // Cross-line repair and ordinary speculative reads are mutually exclusive.
    // Select on the internal repair state, keeping late response/recovery
    // controls out of the private RAM read-index and way data muxes.
    wire i_ram_cross_read=i_ram_cross_lookup||i_ram_cross_error;
    wire i_ram_read=!reset && (i_speculative_read || i_ram_cross_read);
    // Private synchronous read payload is safe at idle or response transfer.
    // Keep actual new_d state/side-effect ownership independently qualified.
    wire d_ram_new_read=d_speculative_read;
    wire d_ram_writeback_read=(d_state==D_WRITE_READ) ||
        (d_state==D_WRITE_BEATS && data_wr_gnt_i && d_beat!=3'd7);
    wire d_first_ram_read=!reset && (d_ram_new_read || (d_ram_writeback_read && !writeback_way));
    wire d_second_ram_read=!reset && ((d_ram_new_read && D_WAYS>1) || (d_ram_writeback_read && writeback_way));
    // Way lookup consumes a cache-line address, not the word address + 4.
    // Query current/adjacent lines independently; select the next line only
    // for the last word. Keep late ownership/redirect muxes after tag reads.
    // 新提案与跨行提案分别计算标签上下文，在RAM时钟边界同步捕获。
    // 预读的路选择仍须与被接受请求的地址及有效快照对应。
    wire [I_INDEX_BITS-1:0] i_offer_set=imem_request_address[6+I_INDEX_BITS-1:6];
    wire [I_TAG_BITS-1:0] i_offer_tag=imem_request_address[31:6+I_INDEX_BITS];
    wire [I_INDEX_BITS-1:0] i_offer_next_set=i_offer_set+1'b1;
    wire [I_TAG_BITS-1:0] i_offer_next_tag=i_offer_tag+(&i_offer_set);
    // Any valid line has a different tag from the opposite way, even when
    // that opposite way is invalid. Refill maintains this invariant below.
    // Therefore the early data-way choice needs only a tag comparison;
    // registered valid bits still independently qualify the actual hit.
    wire [I_TAG_BITS-1:0] i_offer_equal=~(instruction_tags_second[i_offer_set]^i_offer_tag);
    wire [I_TAG_BITS-1:0] i_offer_next_equal=~(instruction_tags_second[i_offer_next_set]^i_offer_next_tag);
    wire [I_INDEX_BITS-1:0] i_cross_lookup_set=i_next_address[6+I_INDEX_BITS-1:6];
    wire [I_TAG_BITS-1:0] i_cross_lookup_equal=~(instruction_tags_second[i_cross_lookup_set]^i_next_address[31:6+I_INDEX_BITS]);
    always @(posedge clk) begin
        if(i_ram_read) begin
            i_even_way_equal<=i_ram_cross_read ? i_cross_lookup_equal :
                (imem_request_address[5:2]==4'd15 ? i_offer_next_equal : i_offer_equal);
            i_odd_way_equal<=i_ram_cross_read ? i_cross_lookup_equal : i_offer_equal;
            i_even_ram_q<=instruction_even[i_even_ram_read_index];
            i_odd_ram_q<=instruction_odd[i_odd_ram_read_index];
            if(I_WAYS>1)begin
                i_even_second_ram_q<=instruction_even_second[i_even_ram_read_index];
                i_odd_second_ram_q<=instruction_odd_second[i_odd_ram_read_index];
            end
        end
        if(d_first_ram_read) d_first_ram_q<={data_segments_byte7[d_ram_read_index],data_segments_byte6[d_ram_read_index],data_segments_byte5[d_ram_read_index],data_segments_byte4[d_ram_read_index],data_segments_byte3[d_ram_read_index],data_segments_byte2[d_ram_read_index],data_segments_byte1[d_ram_read_index],data_segments_byte0[d_ram_read_index]};
        if(d_second_ram_read) d_second_ram_q<={data_segments_second_byte7[d_ram_read_index],data_segments_second_byte6[d_ram_read_index],data_segments_second_byte5[d_ram_read_index],data_segments_second_byte4[d_ram_read_index],data_segments_second_byte3[d_ram_read_index],data_segments_second_byte2[d_ram_read_index],data_segments_second_byte1[d_ram_read_index],data_segments_second_byte0[d_ram_read_index]};
    end

`ifdef VERILATOR
    integer i_distinct_check;
    always @(posedge clk)if(!reset && I_WAYS>1)begin
        for(i_distinct_check=0;i_distinct_check<I_LINES;i_distinct_check=i_distinct_check+1)
            if((instruction_valid[i_distinct_check] || instruction_valid_second[i_distinct_check]) &&
                instruction_tags[i_distinct_check]==instruction_tags_second[i_distinct_check])
                $fatal(1,"Valid instruction line aliases opposite-way tag");
    end
    // Unique tags and the early way selection are correctness invariants,
    // not predictions: no extra cycle or retry is required on a way-1 hit.
    always @(posedge clk)if(!reset && i_state==I_LOOKUP)begin
        if(i_match_first && i_match_second)$fatal(1,"Duplicate instruction tags in one set");
        if(i_next_match_first && i_next_match_second)$fatal(1,"Duplicate next-line tags");
        if(i_hit && i_odd_ram_select && i_odd_read_way!=i_hit_way)$fatal(1,"Early odd way mismatch");
        if(i_hit && i_even_ram_select && i_address[5:2]!=4'd15 && i_even_read_way!=i_hit_way)$fatal(1,"Early even way mismatch");
        if(i_hit && i_fast_cross_hit && i_even_ram_select && i_even_read_way!=i_next_hit_way)$fatal(1,"Early next-line way mismatch");
    end
`endif

    // Prepare error payload independently of current hit/fault qualification.
    // I_ERROR never overwrites its held payload; only the matching original
    // transition below can make these private bits externally meaningful.
    always @(posedge clk)if(!reset)begin
        if(i_state==I_LOOKUP&&!i_crossing&&i_address[5:2]==4'd15)
            i_error_word<=i_word0;
        else if(i_state==I_FILL&&instr_rvalid_i&&i_beat==3'd7)
            i_error_word<=i_first_word;
    end

`ifdef VERILATOR
    // I侧指令数据按奇偶32位银行同步读；两个输出字可来自同一way的不同行。
    // 跨行快速命中必须同时验证第二行标签和可执行地址。
    always @(posedge clk)if(i_ram_read)begin
        if(i_speculative_read&&i_ram_cross_read)$fatal(1,"RAM normal/repair owners overlap");
        if(i_even_ram_read_index!=(i_speculative_read?new_i_even_pair:cross_i_pair)||
